/** Mulberry32 PRNG for stable, reproducible demo values */
function mulberry32(seed: number) {
  let s = seed >>> 0;
  return () => {
    s = (s + 0x6d2b79f5) >>> 0;
    let t = s;
    t = Math.imul(t ^ (t >>> 15), t | 1);
    t ^= t + Math.imul(t ^ (t >>> 7), t | 61);
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}

const rngNext = mulberry32(20261029);
const rngInt = (min: number, max: number) => min + Math.floor(rngNext() * (max - min + 1));
const rngPick = <T>(arr: T[]): T => arr[Math.floor(rngNext() * arr.length)];
const rngChance = (p: number) => rngNext() < p;
const rngMoney = (min: number, max: number) => Math.round((min + rngNext() * (max - min)) * 100) / 100;

/** Current anchor date: 2026-11-03 */
const ANCHOR_DATE = new Date("2026-11-03T12:00:00Z");

function addDaysIso(days: number): string {
  const d = new Date(ANCHOR_DATE);
  d.setDate(d.getDate() + days);
  return d.toISOString().slice(0, 10);
}

function addMonthsIso(months: number, dayOfMonth = 1): string {
  const d = new Date(ANCHOR_DATE);
  d.setMonth(d.getMonth() + months);
  d.setDate(dayOfMonth);
  return d.toISOString().slice(0, 10);
}

